-- title already exists, so it's safe to run twice.
-- Run once in the Supabase SQL Editor.
-- =====================================================================

insert into hr_custom_forms (company_id, title, description, access, status, fields, created_by)
select 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd', 'Independent Subcontractor & Branch Operator Agreement — Kenny Shin (Birmingham)', 'Kenny Shin signed this agreement on paper on 10/15/2026. HR: open the form, attach the signed scan if you have it, and submit. Then Justin Lee (CEO) signs the Company part from Submissions → Complete.', 'internal', 'published', $fields$[{"id":"fksa00","name":"company_name","type":"heading","label":"","style":{},"width":100,"config":{"text":"US IN HOME SERVICES","level":4,"bold":true,"alignment":"center"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa01","name":"title","type":"heading","label":"","style":{},"width":100,"config":{"text":"INDEPENDENT SUBCONTRACTOR & BRANCH OPERATOR AGREEMENT","level":3,"bold":true,"alignment":"center"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa02","name":"parties","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>Company:</strong> US In Home Services (represented by Justin Gho Lee, CEO)</p><p><strong>Subcontractor / Operator:</strong> Kenny Shin (Individually or d/b/a Birmingham Branch)</p><p><strong>Territory:</strong> Birmingham, Alabama Market (Exclusively limited to the 232 Zip Codes set forth in Exhibit A)</p><p><strong>Effective Date:</strong> October 15, 2026</p><p><strong>Term:</strong> One (1) Year from Effective Date (Automatically renewable unless terminated)</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa03","name":"operator_entity","type":"shortText","label":"Operator Business Entity (if applicable)","style":{},"width":100,"config":{},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"placeholder":"Left blank on the signed paper"},{"id":"fksa04","name":"intro","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>THIS INDEPENDENT SUBCONTRACTOR &amp; BRANCH OPERATOR AGREEMENT (the \"Agreement\") is entered into by and between US In Home Services (\"Company\") and Kenny Shin (\"Subcontractor\" or \"Operator\").</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa05","name":"recitals_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"RECITALS","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa06","name":"recitals","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>WHEREAS, Company contracts with third-party client entities, manufacturers, and home warranty providers (\"B2B Clients\") to provide appliance repair and home services; and</p><p>WHEREAS, Subcontractor is an independent business entity operating in the appliance repair industry and desires to accept subcontracted service tickets assigned by Company within the designated Territory, subject to the terms and conditions set forth herein.</p><p>NOW, THEREFORE, in consideration of the mutual covenants and agreements contained herein, the parties agree as follows:</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa07","name":"article_1_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 1. Subcontracted Ticket Operations and Non-Diversion","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa08","name":"article_1","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Scope of Tickets:</strong> Company may, at its sole discretion, assign subcontracted service tickets (\"Tickets\") to Subcontractor. Subcontractor shall independently perform all assigned Tickets in a professional manner.</p><p><strong>2. Exclusive Channel Management:</strong> All Tickets, client leads, and service inquiries provided by or originating from Company’s B2B Clients within the Birmingham branch must be received, assigned, updated, and completed exclusively through Company’s designated channels and AHS platform.</p><p><strong>3. Strict Non-Diversion &amp; Prohibition of Direct Dealing:</strong> Subcontractor shall not accept tickets, direct payments, or side agreements directly from Company’s B2B Clients, nor divert, transfer, or solicit Company-provided clients or tickets to any third party or competing business.</p><p><strong>4. Liquidated Damages for Diversion:</strong> Any unauthorized ticket diversion or direct client solicitation constitutes a material breach. Subcontractor agrees to pay Company $10,000.00 as liquidated damages per unauthorized ticket or diverted client, in addition to immediate agreement termination and legal remedies.</p><p><strong>5. Assigned Territory:</strong> Subcontractor’s service territory is strictly limited to the 232 Zip Codes listed in Exhibit A attached hereto. Subcontractor has no territorial exclusivity. Company reserves the right, at its sole discretion, to modify or adjust Zip Code assignments based on performance, service quality, and customer satisfaction metrics.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa09","name":"article_2_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 2. B2B End-Client Mandates & Operating Standards","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0a","name":"article_2","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Mandatory B2B Standards Compliance:</strong> Subcontractor acknowledges that Company’s B2B Clients mandate strict operating, dress code, identification, and reporting standards as a prerequisite for ticket fulfillment. Subcontractor agrees that Subcontractor and its technicians shall strictly comply with all B2B Client mandates, including wearing Company-designated uniforms, badges, and maintaining required photo/status logs in AHS at Subcontractor’s sole expense.</p><p><strong>2. Independent Personnel Management:</strong> Subcontractor maintains total control over its technicians, staff, and operations. Recruitment, hiring, payroll, employment taxes, workers' compensation, training, tools, and scheduling are Subcontractor’s sole responsibility.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0b","name":"article_3_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 3. Platform Fees, User Licenses, and Account Charges","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0c","name":"article_3","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Mandatory Platform &amp; Account Fees:</strong> Subcontractor shall pay Company for required and utilized software licenses and administrative infrastructure, which shall be deducted from bi-weekly settlements:</p><p>a. AHS System User License Fee: Current applicable per-user fee per settlement cycle.</p><p>b. Company Email &amp; Tech Account License Fee: Current applicable per-user account fee per settlement cycle.</p><p><strong>2. Optional BPO Operating Services:</strong> If selected by Subcontractor, optional BPO administrative support services are billed weekly as follows:</p><p>a. Claims Management Service: $400.00 / week</p><p>b. CSR &amp; Dispatch Service: $400.00 / week</p><p>c. Parts Management System: $400.00 / week</p><p><strong>3. Current Selected Services:</strong> Subcontractor currently subscribes to Claims Management ($400/wk) and CSR Service ($400/wk), totaling $800.00 per week ($1,600.00 per two-week settlement period).</p><p><strong>4. Fee Changes:</strong> Company may update license or service fees upon fourteen (14) days’ advance written notice.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0d","name":"article_4_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 4. BPO Support Scope & Complete Disclaimer of Claim Liability","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0e","name":"article_4","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. BPO Service Hours &amp; Cap:</strong> CSR and Claims Management services provided by Company’s back-office team (Admin Hub Solutions) are limited to a maximum cap of forty (40) total operational hours per week.</p><p><strong>2. NO FRANCHISE FEES / NO GUARANTEE OF B2B PAYOUT:</strong> Subcontractor acknowledges that Company charges ZERO franchise fees, royalty fees, or equity share on Subcontractor's revenue. Company acts solely as a ticket assignor and administrative service facilitator.</p><p><strong>3. ABSOLUTE DISCLAIMER OF LIABILITY FOR CLAIMS:</strong> Company accepts NO financial, legal, or administrative liability whatsoever for any missed, delayed, denied, rejected, or unpaid claims, billing errors, B2B client system glitches, or administrative omissions occurring during CSR or Claims processing. Subcontractor assumes 100% of the financial risk associated with ticket claims approval and reimbursement by B2B Clients. Subcontractor shall not withhold any fees owed to Company due to unpaid or rejected B2B claims.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0f","name":"article_5_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 5. Parts Procurement, Unauthorized Vendor Charges & Mandatory Refund","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0g","name":"article_5","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Independent Parts Procurement:</strong> Subcontractor shall independently order, store, manage, and pay for all repair parts using Subcontractor’s own vendor accounts and funds.</p><p><strong>2. Prohibition of Company Account Usage:</strong> Subcontractor is strictly prohibited from using Company-owned parts, Company vendor accounts, or charging parts orders to Company without prior written authorization from Company’s Parts Department Head (Navin).</p><p><strong>3. Immediate Refund &amp; Administrative Fee for Unauthorized Orders:</strong> In the event Subcontractor, its technicians, or agents mistakenly, accidentally, or unauthorizedly place parts orders using Company accounts or cause Company to incur parts charges, Subcontractor shall IMMEDIATELY reimburse and refund Company 100% of the total order cost PLUS a fifteen percent (15%) administrative processing fee.</p><p><strong>4. Direct Deduction Right:</strong> Company shall have the unconditional right to immediately set off and deduct any unauthorized parts charges and administrative fees directly from Subcontractor’s pending bi-weekly payouts.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0h","name":"article_6_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 6. Bi-Weekly Settlement & Absolute Right of Set-Off","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0i","name":"article_6","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Settlement Terms:</strong> Company shall settle service compensation once every two weeks based on verified AHS system records and agreed job payment rates, less applicable software license fees, BPO service fees, parts reimbursements, and client chargebacks.</p><p><strong>2. Unconditional Right of Set-Off:</strong> Company reserves the absolute right to set off, withhold, or deduct from any amounts owed to Subcontractor any sums necessary to cover:</p><p>a. Unpaid software/email license fees or BPO fees;</p><p>b. Unauthorized parts charges or vendor invoices;</p><p>c. Property damage claims, customer refunds, or B2B client chargebacks caused by Subcontractor;</p><p>d. Liquidated damages or indemnification obligations under this Agreement.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0j","name":"article_7_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 7. Tax Obligations & Form W-9 Prerequisite","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0k","name":"article_7","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Independent Contractor Classification:</strong> Subcontractor is an independent contractor. Nothing in this Agreement shall be construed as creating an employer-employee, joint venture, franchise, or agency relationship.</p><p><strong>2. W-9 Submission Prerequisite:</strong> As a non-negotiable prerequisite to executing this Agreement and receiving any payout settlements, Subcontractor must provide Company with a fully completed and signed IRS Form W-9.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0l","name":"article_8_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 8. Insurance & Absolute Indemnification","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0m","name":"article_8","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Insurance Requirements:</strong> Subcontractor shall, at its own expense, maintain:</p><p>a. Commercial General Liability Insurance (Minimum $1,000,000 per occurrence);</p><p>b. Automobile Liability Insurance for all service vehicles;</p><p>c. Statutory Workers' Compensation Insurance as required by Alabama law.</p><p>Subcontractor shall name \"US In Home Services\" as an Additional Insured and provide certificates of insurance upon request.</p><p><strong>2. Absolute Indemnification:</strong> Subcontractor agrees to defend, indemnify, and hold harmless Company, its officers, directors, employees, and B2B Clients from and against any and all claims, demands, losses, damages, liabilities, lawsuits, judgments, costs, and attorney fees arising out of or related to Subcontractor’s operations, technician misconduct, property damage, personal injury, regulatory non-compliance, or breach of this Agreement.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0n","name":"article_9_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 9. Confidentiality, Non-Solicitation & Non-Competition","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0o","name":"article_9","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Confidential Information:</strong> Subcontractor shall maintain strict confidentiality regarding Company’s B2B Client lists, pricing structures, AHS data, customer records, and operational know-how.</p><p><strong>2. Non-Solicitation &amp; Non-Competition:</strong> During the term of this Agreement and for a period of two (2) years following termination, Subcontractor shall not:</p><p>a. Solicit, contract directly with, or perform appliance repair services for any B2B Client introduced by Company;</p><p>b. Engage in, establish, or operate a competing appliance repair business within the 232 Zip Codes specified in Exhibit A, to the fullest extent enforceable under Alabama law.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0p","name":"article_10_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 10. Term, Immediate Termination & Post-Termination Duties","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0q","name":"article_10","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Term:</strong> This Agreement is effective on the date first written above and continues for a term of one (1) year, automatically renewing annually unless terminated.</p><p><strong>2. Termination for Convenience:</strong> Either party may terminate this Agreement without cause by providing thirty (30) days’ advance written notice.</p><p><strong>3. Immediate Termination for Cause:</strong> Company may terminate this Agreement IMMEDIATELY upon written notice if Subcontractor:</p><p>a. Diverts tickets or deals directly with B2B Clients;</p><p>b. Places unauthorized parts orders on Company accounts;</p><p>c. Fails to maintain required insurance or submit Form W-9;</p><p>d. Commits fraud, criminal misconduct, or causes severe customer/property damage;</p><p>e. Breaches any material provision of this Agreement.</p><p><strong>4. Post-Termination Transition:</strong> Upon termination, Subcontractor shall immediately return all Company property, surrender AHS/email accounts, transition open tickets, and settle all outstanding financial obligations.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0r","name":"article_11_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"Article 11. Governing Law & General Provisions","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0s","name":"article_11","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p><strong>1. Governing Law &amp; Venue:</strong> This Agreement shall be governed by and construed in accordance with the laws of the State of Alabama. Any legal action arising from this Agreement shall be brought exclusively in the state or federal courts located in Jefferson County or Shelby County, Alabama.</p><p><strong>2. Entire Agreement:</strong> This Agreement constitutes the entire understanding between the parties and supersedes all prior agreements. Amendments must be in writing and signed by both parties.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0t","name":"witness_rule","type":"divider","label":"","style":{},"width":100,"config":{"color":"#9ca3af","spacing":8,"lineStyle":"solid","thickness":1},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0u","name":"witness_text","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>IN WITNESS WHEREOF, the parties hereto have executed this Agreement as of the Effective Date written above.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa0v","name":"company_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"COMPANY: US IN HOME SERVICES","level":5,"bold":true,"alignment":"left","signer":{"profileIds":["6ee95872-1f1c-4a0e-95c3-4221a388ff14"],"name":"Justin Lee"}},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fksa0w","name":"ceo_signature","type":"signature","label":"By (Signature)","style":{},"width":50,"config":{"canvasWidth":360,"canvasHeight":120,"penColor":"#0f172a","backgroundColor":"#ffffff","allowClear":true},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fksa0x","name":"ceo_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":false,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"fillBy":"company"},{"id":"fksa0y","name":"ceo_name","type":"shortText","label":"Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Justin Gho Lee","fillBy":"company"},{"id":"fksa0z","name":"ceo_title","type":"shortText","label":"Title","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Chief Executive Officer (CEO)","fillBy":"company"},{"id":"fksa10","name":"subcontractor_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"SUBCONTRACTOR / OPERATOR: Kenny Shin (Birmingham Branch Operator)","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa11","name":"subcontractor_signature","type":"shortText","label":"By (Signature)","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Signed on paper (original on file)"},{"id":"fksa12","name":"subcontractor_date","type":"datePicker","label":"Date","style":{},"width":50,"config":{"minDate":"","maxDate":"","disableWeekends":false,"dateFormat":"MM/DD/YYYY","timeZone":""},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"2026-10-15"},{"id":"fksa13","name":"subcontractor_name","type":"shortText","label":"Name","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Kenny Shin"},{"id":"fksa14","name":"subcontractor_title","type":"shortText","label":"Title","style":{},"width":50,"config":{},"hidden":false,"advanced":{},"readonly":true,"required":true,"validation":{},"displayMode":"block","conditionalLogic":null,"defaultValue":"Authorized Representative"},{"id":"fksa15","name":"signed_paper_copy","type":"fileUpload","label":"Signed paper copy (scan, optional)","style":{},"width":100,"config":{"allowedTypes":".pdf,.jpg,.jpeg,.png","maxSizeMb":20,"maxFiles":1},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa16","name":"exhibit_rule","type":"divider","label":"","style":{},"width":100,"config":{"color":"#9ca3af","spacing":8,"lineStyle":"solid","thickness":1},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa17","name":"exhibit_a_heading","type":"heading","label":"","style":{},"width":100,"config":{"text":"EXHIBIT A: COVERED TERRITORY ZIP CODES (BIRMINGHAM MARKET)","level":5,"bold":true,"alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null},{"id":"fksa18","name":"exhibit_a","type":"paragraph","label":"","style":{},"width":100,"config":{"html":"<p>Total of 232 Authorized Zip Codes:</p><p>35004, 35005, 35006, 35007, 35013, 35014, 35015, 35020, 35021, 35022, 35023, 35032, 35034, 35035, 35036, 35038, 35040, 35042, 35043, 35045, 35046, 35049, 35051, 35053, 35054, 35055, 35057, 35058, 35062, 35063, 35064, 35068, 35071, 35073, 35078, 35079, 35080, 35085, 35091, 35094, 35096, 35097, 35098, 35111, 35114, 35115, 35116, 35117, 35118, 35120, 35121, 35124, 35126, 35127, 35130, 35131, 35133, 35135, 35137, 35139, 35142, 35143, 35144, 35146, 35147, 35148, 35150, 35151, 35171, 35172, 35173, 35175, 35178, 35179, 35180, 35183, 35184, 35186, 35188, 35203, 35204, 35205, 35206, 35207, 35208, 35209, 35210, 35211, 35212, 35213, 35214, 35215, 35216, 35217, 35218, 35221, 35222, 35223, 35224, 35226, 35228, 35229, 35233, 35234, 35235, 35242, 35243, 35244, 35254, 35401, 35404, 35405, 35406, 35442, 35444, 35446, 35452, 35453, 35456, 35463, 35466, 35473, 35474, 35475, 35476, 35490, 35501, 35503, 35504, 35546, 35549, 35565, 35570, 35579, 35580, 35619, 35621, 35640, 35670, 35747, 35754, 35760, 35765, 35769, 35901, 35903, 35904, 35905, 35906, 35907, 35952, 35953, 35954, 35956, 35961, 35962, 35972, 35987, 36006, 36051, 36064, 36080, 36091, 36251, 36258, 36264, 36268, 36271, 36272, 36273, 36277, 36279, 36301, 36303, 36305, 36502, 36507, 36509, 36511, 36518, 36521, 36522, 36523, 36525, 36526, 36527, 36528, 36532, 36535, 36541, 36542, 36544, 36545, 36549, 36551, 36555, 36556, 36558, 36559, 36560, 36561, 36562, 36567, 36571, 36572, 36574, 36575, 36578, 36579, 36580, 36582, 36583, 36584, 36585, 36587, 36590.</p>","text":"","alignment":"left"},"hidden":false,"advanced":{},"readonly":false,"required":false,"validation":{},"displayMode":"block","conditionalLogic":null}]$fields$::jsonb, '78d3504c-56f9-43a0-b7b1-091e3eba7d36'
where exists (select 1 from companies where id = 'b86acc43-08df-4ef3-aae0-1653cb5a1fcd')
